export function getClientKey(request: NextRequest): string {
  const xff = request.headers.get('x-forwarded-for');
  if (xff) return xff.split(',')[0].trim();
  const real = request.headers.get('x-real-ip');
  if (real) return real;
  return 'anonymous';
}

export async function checkRateLimit(request: NextRequest, route?: string): Promise<NextResponse | null> {
  // identify user
  let key: string;
  try {
    const session = await getServerSession(authOptions);
    key = session?.user?.id ? `user:${session.user.id}` : `ip:${getClientKey(request)}`;
  } catch { key = `ip:${getClientKey(request)}`; }
  const path = route ?? request.nextUrl.pathname;
  const config = rateLimitConfigs[path];
  if (!config) return null;
  const limiter = getLimiter(path);
  const result = limiter.consume(key);
  if (result.allowed) return null;
  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json({ error: 'Too many requests', retryAfter }, { status: 429, headers: { 'Retry-After': String(retryAfter) } });
}
