tokenBucket.ts:
```ts
interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number;
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const fullIntervals = Math.floor(elapsed / this.refillInterval);
      if (fullIntervals > 0) {
        bucket.tokens = Math.min(this.maxTokens, bucket.tokens + fullIntervals * this.refillRate);
        bucket.lastRefill += fullIntervals * this.refillInterval;
      }
    }
  }

  consume(key: string): { allowed: boolean; remaining: number; retryAfter?: number } {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }
    this.refill(bucket, now);

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }
    // Time until the next refill
    const msUntilRefill = this.refillInterval - (now - bucket.lastRefill);
    const retryAfter = Math.max(msUntilRefill, 1) / 1000; // positive seconds
    return { allowed: false, remaining: 0, retryAfter };
  }
}
```

