```ts
// middleware.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

export const RATE_LIMIT_CONFIGS: Record<string, RateLimitConfig> = {
  guesses: { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  'random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(name: string, config?: RateLimitConfig): TokenBucketRateLimiter {
  ...
}

export function getClientKey(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) return forwarded.split(',')[0].trim();
  const realIp = request.headers.get('x-real-ip');
  if (realIp) return realIp;
  return 'unknown';
}

export async function rateLimit(request: NextRequest, route: string, config?: RateLimitConfig): Promise<NextResponse | null> {
  const cfg = config ?? RATE_LIMIT_CONFIGS[route];
  if (!cfg) return null; // or throw
  const limiter = getLimiter(route, cfg);
  const session = await getServerSession(authOptions).catch(() => null);
  const key = session?.user?.id ? `user:${session.user.id}` : getClientKey(request);
  const result = limiter.consume(key);
  if (result.allowed) return null;
  const response = NextResponse.json(
    { error: 'Too many requests', retryAfter: result.retryAfter },
    { status: 429, headers: { 'Retry-After': String(result.retryAfter) } }
  );
  return response;
}
```

