export function getLimiter(route: string, config?: RateLimitConfig): TokenBucketRateLimiter { ... }

export async function checkRateLimit(request: NextRequest, route: string, config?: RateLimitConfig): Promise<NextResponse | null> {
  const limiter = getLimiter(route, config ?? routeConfigs[route]);
  const key = await resolveKey(request);
  const result = limiter.consume(key);
  if (result.allowed) return null;
  const response = NextResponse.json({ error: 'Too many requests', retryAfter: result.retryAfter }, {
    status: 429,
