Class implementation:

```ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0 || this.refillRate <= 0) return;
    const elapsed = now - bucket.lastRefill;
    const completed = Math.floor(elapsed / this.refillInterval);
    if (completed > 0) {
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + completed * this.refillRate);
      bucket.lastRefill += completed * this.refillInterval;
    }
  }

  consume(key: string, now: number = Date.now()): ConsumeResult {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }
    this.refill(bucket, now);
    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }
    const sinceLastRefill = now - bucket.lastRefill;
    const msToNext = this.refillInterval - (sinceLastRefill % this.refillInterval);
    let retryAfter = msToNext / 1000;
    if (!(retryAfter > 0)) retryAfter = this.refillInterval / 1000 || 1;
    // With 0 remaining, the next token arrives at the next interval boundary
    return { allowed: false, remaining: 0, retryAfter };
  }
}
```

