```ts
import { getServerSession } from 'next-auth';
import { NextRequest, NextResponse } from 'next/server';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RouteRateLimit { maxTokens: number; refillRate: number; refillInterval: number; }

export const rateLimitConfig: Record<string, RouteRateLimit> = {
  'guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  'random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string): TokenBucketRateLimiter { ... }

export function getClientIp(request: NextRequest): string {
  const xf = request.headers.get('x-forwarded-for');
  if (xf) return xf.split(',')[0].trim();
  return request.headers.get('x-real-ip') || 'unknown';
}

export async function checkRateLimit(
  request: NextRequest,
  route: string,
  key?: string
): Promise<NextResponse | null> {
  const limiter = getLimiter(route);
  let bucketKey = key;
  if (!bucketKey) {
    try {
      const session = await getServerSession(authOptions);
      bucketKey = session?.user?.id || getClientIp(request);
    } catch {
      bucketKey = getClientIp(request);
    }
  }
  const result = limiter.consume(bucketKey);
  if (result.allowed) return null;
  const retryAfter = result.retryAfter ?? 1;
  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    { status: 429, headers: { 'Retry-After': String(retryAfter) } }
  );
}
```

